-- ----------------------------
-- Table structure for ds_budidaya
-- ----------------------------
DROP TABLE IF EXISTS `ds_budidaya`;
CREATE TABLE `ds_budidaya`  (
  `id_tanaman` int NOT NULL AUTO_INCREMENT,
  `id_lokasi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `jenis_tanaman` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `varietas_tanaman` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `tgl_semai` date NULL DEFAULT NULL,
  `populasi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `petugas_budidaya` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id_tanaman`, `id_lokasi`) USING BTREE,
  INDEX `id_tanaman`(`id_tanaman` ASC, `jenis_tanaman` ASC, `varietas_tanaman` ASC, `tgl_semai` ASC) USING BTREE,
  INDEX `id_tanaman_2`(`id_tanaman` ASC) USING BTREE,
  INDEX `fk_budidaya`(`id_lokasi` ASC) USING BTREE,
  CONSTRAINT `fk_budidaya` FOREIGN KEY (`id_lokasi`) REFERENCES `ds_greenhouse` (`id_lokasi`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

