  `waktu_climate` datetime NOT NULL,
  `suhu` float NOT NULL,
  `rh` float NOT NULL,
  PRIMARY KEY (`id_climate`, `id_lokasi`) USING BTREE,
  INDEX `fk_climate`(`id_lokasi` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4072 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

