-- ----------------------------
-- Table structure for ds_foto
-- ----------------------------
DROP TABLE IF EXISTS `ds_foto`;
CREATE TABLE `ds_foto`  (
  `id_foto` int NOT NULL AUTO_INCREMENT,
  `id_layout` int NOT NULL,
  `nama_foto` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `hss_tanaman` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `waktu_foto` datetime NULL DEFAULT NULL,
  `jml_tanamansehat` int NULL DEFAULT NULL,
  `jml_tanamansakit` int NULL DEFAULT NULL,
  PRIMARY KEY (`id_foto`, `id_layout`) USING BTREE,
  INDEX `fk_foto`(`id_layout` ASC) USING BTREE,
  CONSTRAINT `fk_foto` FOREIGN KEY (`id_layout`) REFERENCES `ds_layout` (`id_layout`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 92 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

