-- Table structure for ds_layout
-- ----------------------------
DROP TABLE IF EXISTS `ds_layout`;
CREATE TABLE `ds_layout`  (
  `id_layout` int NOT NULL AUTO_INCREMENT,
  `id_tanaman` int NOT NULL,
  `kode` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `blok` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `tray` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id_layout`, `id_tanaman`) USING BTREE,
  INDEX `fk_layout`(`id_tanaman` ASC) USING BTREE,
  INDEX `id_layout`(`id_layout` ASC) USING BTREE,
  INDEX `id_layout_2`(`id_layout` ASC, `kode` ASC, `blok` ASC, `tray` ASC) USING BTREE,
  CONSTRAINT `fk_layout` FOREIGN KEY (`id_tanaman`) REFERENCES `ds_budidaya` (`id_tanaman`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = Dynamic;

